            a: "<ul style=\"margin:8px 0;font-size:13px;\"><br><li><strong>Offene Betriebsprüfung:</strong> Das Finanzamt prüft noch und könnte Nachzahlungen fordern</li><br></ul><ul style=\"margin:8px 0;font-size:13px;\"><br><li><strong>Verdeckte Gewinnausschüttungen:</strong> Private Ausgaben über das Unternehmen laufen lassen, die steuerlich nicht korrekt behandelt wurden</li><br></ul><ul style=\"margin:8px 0;font-size:13px;\"><br><li><strong>Steuernachzahlungen im Raum:</strong> Hinweise auf Steuerschulden, die den Deal belasten könnten</li><</ul>",
            tags: ["hast", "deal", "vermeiden", "vendor", "flags", "unternehmen", "lassen", "red", "vorab", "diligence"],
